'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = process.env.PORT ? Number(process.env.PORT) : 43100;
const DIST_DIR = path.join(__dirname, '..', 'frontend', 'dist');

const DATA_DIR = process.env.KEEP_DATA_DIR || path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'db.json');

const DEFAULT_DATA = () => ({
  notes: [],
  labels: [
    { id: 'label-default', name: 'Reminders', isDefault: true },
  ],
  settings: {
    view: 'list',
    enableBottom: true,
  },
});

// ---- Durable storage ------------------------------------------------
// The store lives in a JSON file so that user edits, deletions and archive
// state survive restarts. Records are only initialised for a brand-new
// store. A missing file means the store has never existed; an existing file
// (even with an empty note list) is respected as-is.
let db = null;

function loadData() {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }
  if (!fs.existsSync(DATA_FILE)) {
    const initial = DEFAULT_DATA();
    fs.writeFileSync(DATA_FILE, JSON.stringify(initial, null, 2));
    return initial;
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
    // Normalise shape defensively so later nodes can rely on it, but never
    // overwrite user data.
    if (!parsed || typeof parsed !== 'object') {
      return DEFAULT_DATA();
    }
    if (!Array.isArray(parsed.notes)) parsed.notes = [];
    if (!Array.isArray(parsed.labels)) parsed.labels = [];
    if (!parsed.settings || typeof parsed.settings !== 'object') {
      parsed.settings = { view: 'list', enableBottom: true };
    }
    return parsed;
  } catch (err) {
    console.error('[keep] Failed to parse data file, falling back to defaults:', err);
    return DEFAULT_DATA();
  }
}

function persist() {
  try {
    fs.writeFileSync(DATA_FILE, JSON.stringify(db, null, 2));
  } catch (err) {
    console.error('[keep] Failed to persist data:', err);
  }
}

db = loadData();

// ---- Helpers ---------------------------------------------------------
function sendJSON(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function send404(res, message) {
  sendJSON(res, 404, { error: message || 'Not found' });
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 2 * 1024 * 1024) {
        reject(new Error('Request body too large'));
        req.destroy();
        return;
      }
    });
    req.on('end', () => {
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

function isNoteValid(note) {
  return (
    note &&
    typeof note.title === 'string' &&
    typeof note.content === 'string'
  );
}

// ---- API routing ----------------------------------------------------
async function handleApi(req, res, url) {
  const method = req.method;

  if (method === 'GET' && url.pathname === '/api/notes') {
    return sendJSON(res, 200, { notes: db.notes });
  }

  if (method === 'POST' && url.pathname === '/api/notes') {
    let body;
    try {
      body = await parseBody(req);
    } catch (err) {
      return sendJSON(res, 400, { error: err.message });
    }
    if (!isNoteValid(body)) {
      return sendJSON(res, 400, { error: 'title and content are required' });
    }
    const now = new Date().toISOString();
    const note = {
      id: body.id || crypto.randomUUID(),
      title: body.title,
      content: body.content,
      pinned: !!body.pinned,
      archived: !!body.archived,
      deleted: !!body.deleted,
      color: typeof body.color === 'string' ? body.color : '',
      labels: Array.isArray(body.labels) ? body.labels : [],
      createdAt: body.createdAt || now,
      updatedAt: body.updatedAt || now,
    };
    db.notes.push(note);
    persist();
    return sendJSON(res, 201, { note });
  }

  if (method === 'GET' && url.pathname.startsWith('/api/notes/')) {
    const id = decodeURIComponent(url.pathname.slice('/api/notes/'.length));
    const note = db.notes.find((n) => n.id === id);
    if (!note) return send404(res, 'Note not found');
    return sendJSON(res, 200, { note });
  }

  return send404(res, 'Not found');
}

// ---- Static / SPA serving -------------------------------------------
const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.map': 'application/json',
};

function serveStatic(res, filePath) {
  fs.readFile(filePath, (err, content) => {
    if (err) {
      return send404(res, 'Not found');
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
      'Content-Length': content.length,
    });
    res.end(content);
  });
}

// ---- Server ----------------------------------------------------------
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

  try {
    if (url.pathname.startsWith('/api/')) {
      return await handleApi(req, res, url);
    }

    // Serve a file from dist, falling back to index.html for SPA routing.
    let filePath = path.normalize(path.join(DIST_DIR, url.pathname));
    if (!filePath.startsWith(DIST_DIR)) {
      return send404(res, 'Not found');
    }

    fs.stat(filePath, (statErr, stats) => {
      if (!statErr && stats.isFile()) {
        return serveStatic(res, filePath);
      }
      if (!statErr && stats.isDirectory()) {
        return serveStatic(res, path.join(filePath, 'index.html'));
      }
      // SPA fallback: serve the home page shell for unknown routes.
      return serveStatic(res, path.join(DIST_DIR, 'index.html'));
    });
  } catch (err) {
    console.error('[keep] Unhandled request error:', err);
    if (!res.headersSent) {
      sendJSON(res, 500, { error: 'Internal server error' });
    } else {
      res.end();
    }
  }
});

server.listen(PORT, () => {
  console.log(`[keep] server listening on http://localhost:${PORT}`);
});

process.on('uncaughtException', (err) => {
  console.error('[keep] uncaught exception:', err);
});

import { HomePage } from './components/HomePage.js';

