function render() {
  root.innerHTML = '';
  const app = HomePage();
  root.appendChild(app);
}

render();

import { Sidebar } from './Sidebar.js';
import { NoteComposer } from './NoteComposer.js';

/**
 * Home page (REQ-1.1).
 *
 * This node only requires that the home page renders with a "Take a note..."
 * composer trigger and a "Search" entry, plus the header/sidebar shell used by
 * downstream nodes. All data is rendered client-side from the notes API in
 * later nodes; here we render the static shell so the page loads without JS
 * errors.
 */
export function HomePage() {
  const container = document.createElement('div');
  container.className = 'app-shell';

  const header = document.createElement('header');
  header.className = 'app-header';

  const headerLeft = document.createElement('div');
  headerLeft.className = 'header-left';

  // Sidebar toggle (Main menu)
  const menuButton = document.createElement('button');
  menuButton.type = 'button';
  menuButton.className = 'icon-button menu-button';
  menuButton.setAttribute('aria-label', 'Main menu');
  menuButton.setAttribute('title', 'Main menu');
  menuButton.innerHTML =
    '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path fill="currentColor" d="M3 6h18v2H3V6zm0 5h18v2H3v-2zm0 5h18v2H3v-2z"/></svg>';
  headerLeft.appendChild(menuButton);

  const brand = document.createElement('span');
  brand.className = 'brand';
  brand.textContent = 'Keep';
  headerLeft.appendChild(brand);

  header.appendChild(headerLeft);

  // Search entry
  const searchWrap = document.createElement('div');
  searchWrap.className = 'search-wrap';
  const searchInput = document.createElement('input');
  searchInput.type = 'search';
  searchInput.className = 'search-input';
  searchInput.setAttribute('role', 'searchbox');
  searchInput.setAttribute('placeholder', 'Search');
  searchInput.setAttribute('aria-label', 'Search');
  searchInput.setAttribute('aria-placeholder', 'Search');
  searchWrap.appendChild(searchInput);
  header.appendChild(searchWrap);

  const headerRight = document.createElement('div');
  headerRight.className = 'header-right';

  // View toggle (REQ-5.x)
  const viewButton = document.createElement('button');
  viewButton.type = 'button';
  viewButton.className = 'icon-button view-button';
  viewButton.setAttribute('aria-label', 'List view');
  viewButton.textContent = 'List view';
  viewButton.setAttribute('title', 'List view');
  headerRight.appendChild(viewButton);

  // Settings entry (REQ-4.x)
  const settingsButton = document.createElement('button');
  settingsButton.type = 'button';
  settingsButton.className = 'icon-button settings-button';
  settingsButton.setAttribute('aria-label', 'Settings');
  settingsButton.textContent = 'Settings';
  settingsButton.setAttribute('title', 'Settings');
  headerRight.appendChild(settingsButton);

  header.appendChild(headerRight);

  const body = document.createElement('div');
  body.className = 'app-body';

  const sidebar = Sidebar();
  const main = document.createElement('main');
  main.className = 'app-main';

  const composer = NoteComposer();
  main.appendChild(composer);

  const notesArea = document.createElement('div');
  notesArea.className = 'notes-area';
  notesArea.setAttribute('data-testid', 'notes-area');
  main.appendChild(notesArea);

  body.appendChild(sidebar);
  body.appendChild(main);

  container.appendChild(header);
  container.appendChild(body);

  return container;
}

/**
 * Sidebar navigation (REQ-1.1 / REQ-6.2).
 *
 * The sidebar is expanded by default and exposes the "Notes" label so that
 * openSidebar/openHome helpers treat it as already open (a no-op). The header
 * "Main menu" toggle collapses/reopens it (REQ-6.2). Downstream nodes add
 * Trash / Archive / labels entries here.
 */
export function Sidebar() {
  const aside = document.createElement('aside');
  aside.className = 'sidebar';
  aside.setAttribute('aria-label', 'Main navigation');

  const nav = document.createElement('nav');
  nav.className = 'sidebar-nav';

  // Notes entry
  const notesItem = document.createElement('button');
  notesItem.type = 'button';
  notesItem.className = 'sidebar-item active';
  notesItem.setAttribute('aria-label', 'Notes');
  notesItem.textContent = 'Notes';
  nav.appendChild(notesItem);

  aside.appendChild(nav);
  return aside;
}

/**
 * Note composer trigger (REQ-1.1 / REQ-2.2).
 *
 * REQ-1.1 only requires the "Take a note..." text to be visible. The composer
 * expands into a title + content editor when clicked; autosave on close is
 * handled by downstream nodes (REQ-2.2). The trigger here is kept simple and
 * exposes the expected accessible label.
 */
export function NoteComposer() {
  const container = document.createElement('div');
  container.className = 'composer';

  const form = document.createElement('div');
  form.className = 'composer-form';

  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'composer-trigger';
  input.setAttribute('placeholder', 'Take a note...');
  input.setAttribute('aria-label', 'Take a note...');
  input.setAttribute('readonly', '');
  input.textContent = 'Take a note...';
  input.value = '';

  form.appendChild(input);
  container.appendChild(form);
  return container;
}

