import { readFileSync, writeFileSync, mkdirSync, cpSync, rmSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const distDir = join(__dirname, 'dist');
const srcDir = join(__dirname, 'src');

// Fresh output directory.
rmSync(distDir, { recursive: true, force: true });
mkdirSync(distDir, { recursive: true });

// Copy the entry HTML and static stylesheet.
cpSync(join(__dirname, 'index.html'), join(distDir, 'index.html'));
cpSync(join(__dirname, 'styles.css'), join(distDir, 'styles.css'));

// Copy the JS module sources into dist, preserving the src/ layout so the
// browser can resolve the module imports.
function copyJs(dir) {
  for (const name of ['App.js', 'components', 'style.css']) {
    // no-op guard
  }
  const entries = readDir(dir);
  for (const entry of entries) {
    const full = join(dir, entry);
    const rel = full.slice(srcDir.length + 1);
    if (entry.endsWith('.js')) {
      const out = join(distDir, 'src', rel);
      mkdirSync(dirname(out), { recursive: true });
      writeFileSync(out, readFileSync(full, 'utf8'));
    }
  }
}

function readDir(dir) {
  const { readdirSync } = awaitImport();
  return readdirSync(dir);
}

function awaitImport() {
  const { readdirSync } = importModule('node:fs');
  return { readdirSync };
}

function importModule(name) {
  return import(name);
}

copyJs(srcDir);

// Also copy any non-JS assets inside src (rare), mirroring structure.
copyAssets(srcDir);

function copyAssets(dir) {
  const { readdirSync, statSync } = importModule('node:fs');
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      copyAssets(full);
    } else if (!entry.endsWith('.js')) {
      const rel = full.slice(srcDir.length + 1);
      const out = join(distDir, 'src', rel);
      mkdirSync(dirname(out), { recursive: true });
      writeFileSync(out, readFileSync(full));
    }
  }
}

