import { expect, Locator, Page } from '@playwright/test';

type Scope = Page | Locator;
type Match = string | RegExp | Array<string | RegExp>;

export const FIXTURES = {
  notes: {
    pinnedTitle: 'Sprint goals',
    regularTitle: 'Groceries',
