/**
 * Fetch the available notes from the API and render them in two separated
 * sections: pinned notes under a "Pinned" heading, regular notes under an
 * "Others" heading (REQ-2.1).
 */
async function loadNotes(notesArea) {
  notesArea.textContent = '';
  try {
    const res = await fetch('/api/notes');
    if (!res.ok) throw new Error('Failed to load notes');
    const data = await res.json();
    const notes = Array.isArray(data.notes) ? data.notes : [];

    // Only show notes that are not deleted and not archived.
    const visible = notes.filter((n) => !n.deleted && !n.archived);
    const pinned = visible.filter((n) => n.pinned);
    const others = visible.filter((n) => !n.pinned);

    if (pinned.length) {
      const pinnedSection = buildSection('Pinned', pinned);
      notesArea.appendChild(pinnedSection);
    }
    if (others.length) {
      const othersSection = buildSection('Others', others);
      notesArea.appendChild(othersSection);
    }
  } catch (err) {
    console.error('[keep] Failed to load notes:', err);
  }
}

function buildSection(title, notes) {
  const section = document.createElement('section');
  section.className = 'notes-section';

  const heading = document.createElement('h2');
  heading.className = 'notes-section-heading';
  heading.textContent = title;
  section.appendChild(heading);

  const list = document.createElement('div');
  list.className = 'notes-list';
  notes.forEach((note) => {
    list.appendChild(buildNote(note));
  });
  section.appendChild(list);

  return section;
}

function buildNote(note) {
  const card = document.createElement('article');
  card.className = 'note-card';
  card.dataset.noteId = note.id;

  const title = document.createElement('h3');
  title.className = 'note-card-title';
  title.textContent = note.title;
  card.appendChild(title);

  if (note.content) {
    const content = document.createElement('p');
    content.className = 'note-card-content';
    content.textContent = note.content;
    card.appendChild(content);
  }

  return card;
}

